use std::f64::consts::PI;
pub type V = [f64; 2];
fn add(a:V,b:V)->V {[a[0]+b[0],a[1]+b[1]]}
fn sub(a:V,b:V)->V {[a[0]-b[0],a[1]-b[1]]}
fn scale(a:V,n:f64)->V {[a[0]*n,a[1]*n]}
fn dot(a:V,b:V)->f64 {a[0]*b[0]+a[1]*b[1]}
fn rotate(a:V,n:f64)->V {let c=n.cos();let s=n.sin();[a[0]*c-a[1]*s,a[0]*s+a[1]*c]}
fn heading(a:V)->f64 {a[1].atan2(a[0])}
fn signed(n:f64)->f64 {n.sin().atan2(n.cos())}
fn sign(n:f64)->f64 {if n==0.0{n}else if n>0.0{1.0}else{-1.0}}
pub fn length(v:V)->f64 {let a=v[0].abs();let b=v[1].abs();if a==f64::INFINITY||b==f64::INFINITY{return f64::INFINITY;}let m=if a>b{a}else{b};if m==0.0&&a==0.0{return 0.0;}let r=if a>b{b}else{a}/m;(1.0+r*r).sqrt()*m}
pub fn hypot(v:V)->f64 {let a=v[0].abs();let b=v[1].abs();let m=a.max(b);if m==f64::INFINITY{return m;}if m==0.0{return 0.0;}let x=a/m;let y=b/m;(x*x+y*y).sqrt()*m}
fn normalized(v:V)->V {let n=length(v);if n>0.00001{[v[0]/n,v[1]/n]}else{v}}
fn clamp(v:V,n:f64)->V {let size=length(v);if size>n{scale(v,n/size)}else{v}}
fn lerp(a:V,b:V,t:f64)->V {add(a,scale(sub(b,a),t))}
fn mass_response(n:f64)->f64 {2.5f64.min(1000.0/1.0f64.max(n))}

