impl Projectile {pub fn supported(&self)->bool {!self.damaged&&!self.collision_disabled&&!self.mine&&!self.flare&&!self.hull_explosion&&!self.ballistic_beam&&(self.rocket||self.ballistic||self.plasma)}pub fn mass(&self)->f64 {0.4f64.max(self.radius*self.radius+self.base_damage.unwrap_or(self.damage)/180.0)}}
