#[derive(Clone,Default)] pub struct Observation {pub ships:Vec<Ship>,pub projectiles:Vec<Projectile>,pub environments:Vec<Environment>}
impl Observation {
    fn ship(&self,id:Identity)->Result<&Ship,Error> {self.ships.iter().find(|s|s.id==id).ok_or(Error::Stale)}
    fn projectile(&self,id:Identity)->Result<&Projectile,Error> {self.projectiles.iter().find(|p|p.id==id).ok_or(Error::Stale)}
    pub fn resolve(&self,t:Target)->Result<Option<Body>,Error> {
        match t.kind {
            BodyKind::Ship=>{let s=match self.ships.iter().find(|s|s.id==t.identity){Some(s)=>s,None=>{return if self.ships.iter().any(|s|s.id.slot==t.identity.slot){Err(Error::Stale)}else{Ok(None)};}};if !s.live(){return Ok(None);}let root=self.ship(s.root)?;if !root.live(){return Ok(None);}
                let members:Vec<_>=self.ships.iter().filter(|s|s.root==root.id&&s.live()).collect();let mut radius=root.radius;let mut mass=0.0;
                for s in members {radius=radius.max(length(sub(root.position,s.position))+s.radius);mass+=1.0f64.max(s.mass);}
                Ok(Some(Body{target:Target{kind:BodyKind::Ship,identity:root.id},position:root.position,velocity:root.velocity,radius,mass:if mass!=0.0{mass}else{root.mass},fixed:root.fixed,team:root.team}))},
            BodyKind::Projectile=>{let p=match self.projectiles.iter().find(|p|p.id==t.identity){Some(p)=>p,None=>{return if self.projectiles.iter().any(|p|p.id.slot==t.identity.slot){Err(Error::Stale)}else{Ok(None)};}};if !p.supported()||p.range<=0.0||p.fade>0.0{return Ok(None);}Ok(Some(Body{target:t,position:p.position,velocity:p.velocity,radius:p.radius,mass:p.mass(),fixed:false,team:p.team}))},
            _=>{let e=match self.environments.iter().find(|e|e.target==t){Some(e)=>e,None=>{return if self.environments.iter().any(|e|e.target.kind==t.kind&&e.target.identity.slot==t.identity.slot){Err(Error::Stale)}else{Ok(None)};}};if !e.alive{return Ok(None);}Ok(Some(Body{target:t,position:e.position,velocity:e.velocity,radius:e.radius,mass:e.mass,fixed:e.fixed,team:None}))},
        }
    }
}
fn same_team(a:Option<f64>,b:Option<f64>)->bool {a.is_some()&&a==b}

/// All methods are synchronous resident Rust queries/actions. Any Err aborts the
/// complete caller step, including source bindings, RNG, HP and presentation.
/// Geometry delegates to the existing Rust hull/shield/weak-hulk implementation;
/// callers may not replace it with bounding circles or JS callbacks.
pub trait Host {
    fn observe(&self)->Result<Observation,Error>;
    /// Original allSystems order, including placeholders for these borrowed slots.
    fn reservations(&self,owner:Identity)->Result<Vec<(u32,f64)>,Error>;
    fn locale_compare(&self,a:&str,b:&str)->Result<Ordering,Error>;
    fn segment_entry(&self,target:Target,start:V,end:V)->Result<Option<f64>,Error>;
    fn pointer_distance(&self,body:&Body,point:V)->Result<f64,Error>;
    fn owner_contains(&self,owner:Identity,point:V)->Result<bool,Error>;
    fn line_clear(&self,owner:Identity,body:&Body,muzzle:V)->Result<bool,Error>;
    fn muzzle(&self,owner:Identity,mount:u32,angle:f64)->Result<V,Error>;
    fn target_key(&self,target:Target)->Result<String,Error>;
    fn increase_flux(&mut self,owner:Identity,amount:f64)->Result<(),Error>;
    fn velocity(&mut self,target:Target,velocity:V,deflected:bool,facing:Option<f64>)->Result<(),Error>;
    fn sync_modules(&mut self,root:Identity)->Result<(),Error>;
    fn capture_projectile(&mut self,target:Identity,owner:Identity)->Result<(),Error>;
    fn binding(&mut self,target:Identity,binding:Binding)->Result<(),Error>;
    fn hulk_managed(&mut self,target:Identity)->Result<(),Error>;
    /// Actual ENERGY shield-hard-flux -> armor/components -> hull path. Computes
    /// live source weapon/CR/outgoing/target CR stats in original multiply order.
    fn tidal_hit(&mut self,owner:Identity,target:Identity,from:V,raw:f64,strength:f64,continuous:bool)->Result<Option<V>,Error>;
}
