impl Kind {pub fn from_id(id:&str)->Option<Self>{Some(match id {"WEB_GRAVITY_WELL"=>Self::Well,"WEB_GRAVITY_REPULSOR"=>Self::Repulsor,"WEB_GRAVITY_VECTOR_TURN"=>Self::Maneuver,"WEB_GRAVITY_REMOTE_RELEASE"=>Self::Release,"WEB_GRAVITY_BATTLE_WELL"=>Self::BattleWell,"WEB_GRAVITY_COLLAPSE"=>Self::Collapse,"WEB_GRAVITY_POLARITY"=>Self::Polarity,"WEB_GRAVITY_BATTLE_REPULSOR"=>Self::BattleRepulsor,"WEB_GRAVITY_DIRECTIONAL_PUSH"=>Self::Push,_=>return None})}
    fn field(self)->bool {matches!(self,Self::Well|Self::Repulsor|Self::Release|Self::BattleWell|Self::BattleRepulsor)}fn remote(self)->bool {matches!(self,Self::Release|Self::Collapse)}}
