#[derive(Clone)] pub struct Slot {pub owner:Identity,pub kind:Kind,pub name:String,pub spec:Spec,pub lifecycle:System,pub field_spec:Option<FieldSpec>,pub collapse_spec:Option<CollapseSpec>,pub auto:Option<AutoCollapse>,pub maneuver_spec:Option<ManeuverSpec>,pub push_spec:Option<PushSpec>,pub input:Option<ActivationInput>,pub field:Option<Field>,pub maneuver:Option<Maneuver>,pub push:Option<Push>,pub polarity:Option<i32>,pub held:bool,pub interrupt_revision:u64}
impl Slot {
    pub fn new(owner:Identity,id:u32,kind:Kind,name:String,spec:Spec)->Self {Self{owner,kind,name,lifecycle:System::new(id,1,&spec),spec,field_spec:None,collapse_spec:None,auto:None,maneuver_spec:None,push_spec:None,input:None,field:None,maneuver:None,push:None,polarity:if kind==Kind::Polarity{Some(1)}else{None},held:false,interrupt_revision:0}}
    pub fn interrupt(&mut self){self.held=false;if self.kind.field()||self.kind==Kind::Collapse{self.field=None;}if self.kind==Kind::Maneuver{self.maneuver=None;}if self.kind==Kind::Push{self.push=None;}self.lifecycle.interrupt(&self.effective_spec());}
    pub fn reset(&mut self){self.interrupt();self.lifecycle.reset(&self.spec);self.input=None;self.polarity=if self.kind==Kind::Polarity{Some(1)}else{None};}
    /// Source Ship.prepareStep barriers; caller skips dead/retreated ordinary update.
    pub fn cancel_before_update(&mut self,s:&Ship,dt:f64){if self.kind==Kind::Polarity{return;}if s.owner.dead||s.owner.retreated||s.owner.hp<=0.0{self.interrupt();return;}if dt>0.0&&(s.owner.retreating||self.kind==Kind::Maneuver&&s.brake){self.interrupt();}}
    pub fn cancel_after_readiness(&mut self,s:&Ship,flamed:bool){if s.owner.overloaded||s.owner.venting||self.kind==Kind::Maneuver&&self.lifecycle.active&&flamed{self.interrupt();}}
    fn effective_spec(&self)->Spec {let mut s=self.spec.clone();if self.field.as_ref().is_some_and(|f|f.kind==FieldKind::Collapse){if let Some(a)=self.auto{s.up=a.up;s.active=a.active;}}s}
    pub fn expire<H:Host>(&mut self,host:&mut H,obs:&mut Observation)->Result<(),Error>{let s=obs.ship(self.owner)?;
        if let (Some(a),Some(c),Some(f))=(self.auto,self.collapse_spec,self.field.as_ref()) {if self.lifecycle.state==ACTIVE&&f.kind==FieldKind::Well&&s.online()&&!self.lifecycle.disabled&&hypot(sub(s.position,f.position))<=self.field_spec.ok_or(Error::Unsupported)?.placement&&s.total_flux+self.lifecycle.pending_flux+a.cost<=s.max_flux {
            let p=f.position;host.increase_flux(self.owner,a.cost)?;obs.ships.iter_mut().find(|s|s.id==self.owner).ok_or(Error::Stale)?.total_flux+=a.cost;
            self.held=false;self.lifecycle.serial+=1.0;self.field=Some(collapse_field(self.lifecycle.serial,p,a.active,c.radius));self.lifecycle.state=IN;self.lifecycle.active=true;self.lifecycle.effect=0.0;self.lifecycle.stage_timer=a.up;self.lifecycle.active_timer=a.up;return Ok(());}}
        self.begin_out();Ok(())
    }
    fn begin_active(&mut self){let d=self.effective_spec();let l=&mut self.lifecycle;l.state=ACTIVE;l.effect=1.0;l.active=true;l.stage_timer=d.active;l.active_timer=if d.active.is_finite(){d.active}else{d.max_duration};l.pending_active+=1.0;if d.active==0.0{self.begin_out();}}
    fn begin_out(&mut self){let d=self.effective_spec();let l=&mut self.lifecycle;l.out_level=l.effect.clamp(0.0,1.0);l.state=OUT;l.active=true;l.stage_timer=d.down*l.effect.clamp(0.0,1.0);l.active_timer=l.stage_timer;if l.stage_timer<=0.0{self.finish_out();}}
    fn finish_out(&mut self){let l=&mut self.lifecycle;l.effect=0.0;l.active=false;l.active_timer=0.0;l.cooling=self.spec.cooldown>0.0;l.state=if l.cooling{COOLDOWN}else{lifecycle::IDLE};l.stage_timer=self.spec.cooldown;l.cooldown_timer=self.spec.cooldown;}
    /// Shared lifecycle with native source's expire hook at ACTIVE end. Regeneration
    /// happens once with the full dt, not once per consumed stage slice.
    pub fn update<H:Host>(&mut self,host:&mut H,dt:f64)->Result<(),Error>{if !dt.is_finite()||dt<=0.0{return Ok(());}let mut obs=host.observe()?;let mut remaining=dt;
        while remaining>1e-9&&self.lifecycle.state!=lifecycle::IDLE {if self.lifecycle.stage_timer==f64::INFINITY{self.lifecycle.effect=1.0;break;}let used=remaining.min(self.lifecycle.stage_timer);
            self.lifecycle.stage_timer=(self.lifecycle.stage_timer-used).max(0.0);remaining-=used;
            if self.lifecycle.state==COOLDOWN{self.lifecycle.cooldown_timer=self.lifecycle.stage_timer;}else{self.lifecycle.active_timer=self.lifecycle.stage_timer;}
            let spec=self.effective_spec();if self.lifecycle.state==IN{self.lifecycle.effect=if spec.up!=0.0{1.0-self.lifecycle.stage_timer/spec.up}else{1.0};}else if self.lifecycle.state==OUT{self.lifecycle.effect=if spec.down!=0.0{self.lifecycle.stage_timer/spec.down}else{0.0};}
            if self.lifecycle.stage_timer>1e-9{break;}match self.lifecycle.state{IN=>self.begin_active(),ACTIVE=>self.expire(host,&mut obs)?,OUT=>self.finish_out(),_=>{self.lifecycle.state=lifecycle::IDLE;self.lifecycle.cooling=false;self.lifecycle.cooldown_timer=0.0;}}
        }
        let mut regen=self.spec.clone();regen.up=0.0;regen.active=0.0;regen.down=0.0;let saved=self.lifecycle.state;let timer=self.lifecycle.stage_timer;self.lifecycle.state=lifecycle::IDLE;self.lifecycle.update(&regen,dt);self.lifecycle.state=saved;self.lifecycle.stage_timer=timer;Ok(())
    }
}
