fn budget(rows:&[(Target,V)],limit:f64,map:&mut Vec<(Target,Delta)>,impulse:bool)->f64 {let total=rows.iter().fold(0.0,|n,(_,v)|n+length(*v));let n=if total>limit{limit/total}else{1.0};for (t,v) in rows {let i=map.iter().position(|(a,_)|a==t).unwrap_or_else(||{map.push((*t,Delta::default()));map.len()-1});let d=&mut map[i].1;if impulse{d.impulse=add(d.impulse,scale(*v,n));}else{d.continuous=add(d.continuous,scale(*v,n));}}total.min(limit)}
