fn turret_aim(current:f64,base:f64,target:f64,arc:f64,rate:f64,pivot:f64,dt:f64)->f64{let half=PI.min(arc*PI/360.0);let unlimited=arc>=360.0;let bound=|n:f64|if unlimited{signed(n)}else{signed(n).clamp(-half,half)};let relative=bound(current-base);let desired=bound(target-base);let error=if unlimited{signed(desired-relative)}else{desired-relative};let opposed=if sign(error)!=sign(pivot)&&rate>0.0{pivot.abs()}else{0.0};let effective=rate.max(opposed-5.0*PI/180.0);base+relative+sign(error)*error.abs().min(effective.max(0.0)*dt)}

/// Exact HulkGeometry weak-polygon helpers. Doubled bridges are not physical
/// edges; source transforms world points by -facing then adds localOffset.
pub fn polygon_area(points:&[V])->f64 {let mut sum=0.0;for (i,p) in points.iter().enumerate(){let q=points[(i+1)%points.len()];sum+=p[0]*q[1]-p[1]*q[0];}sum/2.0}
pub fn hulk_mass(source_mass:f64,bounds:&[V],source_bounds:&[V])->f64{50.0f64.max(source_mass*polygon_area(bounds).abs()/1.0f64.max(polygon_area(source_bounds).abs()))}
fn hulk_edges(bounds:&[V])->Vec<(V,V)>{let near=|a:V,b:V|(a[0]-b[0]).abs()<0.1&&(a[1]-b[1]).abs()<0.1;let mut rows=Vec::new();for(i,a)in bounds.iter().enumerate(){let b=bounds[(i+1)%bounds.len()];if near(*a,b){continue;}if bounds.iter().enumerate().any(|(j,c)|j!=i&&near(b,*c)&&near(*a,bounds[(j+1)%bounds.len()])){continue;}rows.push((*a,b));}rows}
pub fn point_in_hulk(point:V,bounds:&[V])->bool{let mut inside=false;for(a,b)in hulk_edges(bounds){let ab=sub(b,a);let d=dot(ab,ab);let t=(dot(sub(point,a),ab)/if d==0.0{1.0}else{d}).clamp(0.0,1.0);if length(sub(point,add(a,scale(ab,t))))<0.00001{return true;}if (a[1]>point[1])!=(b[1]>point[1])&&point[0]<(b[0]-a[0])*(point[1]-a[1])/(b[1]-a[1])+a[0]{inside=!inside;}}inside}
