            for m in self.mounts.iter_mut().filter(|m|m.owner==owner){let Some(spec)=m.tractor_spec else{continue;};let Some(damage)=spec.tidal_damage else{continue;};if damage==0.0||m.disabled||m.tractor.as_ref().is_none_or(|t|t.phase!=Phase::Hold||t.target.is_none()){continue;}let target=m.tractor.as_ref().unwrap().target.unwrap();let b=obs.resolve(target)?;let body=match b{Some(b)if b.target.kind==BodyKind::Ship&&b.target.identity!=s.root&&!same_team(s.team,b.team)=>b,_=>{m.tractor.as_mut().unwrap().damage_clock=Some(0.0);continue;}};let from=host.muzzle(owner,m.id,m.angle)?;let entry=host.segment_entry(body.target,from,body.position)?;let clear=if let Some(t)=entry{length(sub(from,lerp(from,body.position,t)))<=m.range&&host.line_clear(owner,&body,from)?}else{false};if !clear{m.release("潮汐连接中断");continue;}let cost=spec.tidal_flux.unwrap_or(0.0)*dt;if obs.ship(owner)?.total_flux+cost>s.max_flux{m.release("潮汐幅能不足");continue;}spend(host,&mut obs,owner,cost)?;let state=m.tractor.as_mut().unwrap();let clock=state.damage_clock.get_or_insert(0.0);*clock+=dt;let steps=((*clock+1e-9)/0.1).floor();if steps<=0.0{continue;}*clock-=steps*0.1;
                if let Some(point)=host.tidal_hit(owner,body.target.identity,from,damage*steps*0.1,damage,true)?{state.contact=point;state.status="已抓住 · 敌舰潮汐撕扯".into();}obs=host.observe()?;
            }
            let indices:Vec<_>=self.slots.iter().enumerate().filter(|(_,a)|a.owner==owner).map(|(i,_)|i).collect();for i in indices{let slot=&mut self.slots[i];let Some(spec)=slot.collapse_spec else{continue;};if slot.lifecycle.disabled{slot.interrupt();continue;}if slot.field.is_some()&&slot.lifecycle.state!=IN&&slot.lifecycle.state!=ACTIVE{slot.field=None;continue;}if slot.field.as_ref().is_none_or(|f|f.kind!=FieldKind::Collapse)||slot.lifecycle.state!=ACTIVE{continue;}let field=slot.field.as_mut().unwrap();field.age+=dt;if field.collapsed==Some(true){continue;}field.collapsed=Some(true);let from=field.position;let mut rows=Vec::new();for ship in &obs.ships{if !ship.live()||same_team(s.team,ship.team){continue;}let t=host.segment_entry(Target{kind:BodyKind::Ship,identity:ship.id},from,ship.position)?;let distance=t.map_or(f64::INFINITY,|t|length(sub(from,lerp(from,ship.position,t))));if distance<=spec.radius{rows.push((ship.id,ship.root,distance,ship.name.clone()));}}
                for k in 1..rows.len(){let mut j=k;while j>0{let order=if rows[j].2==rows[j-1].2{host.locale_compare(&rows[j].3,&rows[j-1].3)?}else{rows[j].2.total_cmp(&rows[j-1].2)};if order!=Ordering::Less{break;}rows.swap(j,j-1);j-=1;}}let mut roots=Vec::new();for (id,root,distance,_) in rows{if roots.contains(&root)||roots.len()>=spec.max_ships{continue;}let body=obs.resolve(Target{kind:BodyKind::Ship,identity:id})?;let Some(mut body)=body else{continue;};body.position=obs.ship(id)?.position;body.target=Target{kind:BodyKind::Ship,identity:id};if !host.line_clear(owner,&body,from)?{continue;}roots.push(root);let raw=spec.edge+(spec.damage-spec.edge)*(1.0-distance/spec.radius).max(0.0);host.tidal_hit(owner,id,from,raw,raw,false)?;field.ship_hits.push(root);obs=host.observe()?;}
            }
